new_apply_site = r'''function ct(key,fallback){const v=contentSettings?.[key];return v!==undefined&&v!==null&&String(v)!==''?String(v):String(fallback??CONTENT_DEFAULTS[key]??'')}function tpl(key,vars={},fallback){let s=ct(key,fallback);Object.entries(vars).forEach(([k,v])=>s=s.split('{'+k+'}').join(String(v)));return s}const categoryDisplayKeys={'الهواتف':'categoryPhones','الكمبيوتر':'categoryComputers','الإكسسوارات':'categoryAccessories','الساعات':'categoryWatches','السماعات':'categoryHeadphones'};function displayCategory(name){return ct(categoryDisplayKeys[name],name)}function statusLabel(s){const x=statusMap[s]||statusMap.new;return ct(x.key,x.fallback)}
function applySiteContent(c={}){contentSettings={...CONTENT_DEFAULTS,...c};const map=[['siteHeroLabel','heroLabel'],['siteHeroText','heroText'],['siteHeroButton','heroButton'],['siteTrust1Title','trust1Title'],['siteTrust1Text','trust1Text'],['siteTrust2Title','trust2Title'],['siteTrust2Text','trust2Text'],['siteTrust3Title','trust3Title'],['siteTrust3Text','trust3Text'],['siteTrust4Title','trust4Title'],['siteTrust4Text','trust4Text'],['siteCategoriesTitle','categoriesTitle'],['siteProductsTitle','productsTitle'],['viewAllCategoriesText','viewAllText'],['viewAllProductsText','viewAllText'],['productBrandLabel','productBrandLabel'],['productWarrantyLabel','productWarrantyLabel'],['productDetailsTitle','productDetailsTitle'],['detailAdd','addCartText'],['categoriesPageTitle','categoriesPageTitle'],['categoriesPageSubtitle','categoriesPageSubtitle'],['cartPageTitle','cartPageTitle'],['cartPageSubtitle','cartPageSubtitle'],['cartSectionTitle','cartSectionTitle'],['cartTotalLabel','cartTotalLabel'],['checkoutBtn','checkoutButton'],['ordersSectionTitle','ordersSectionTitle'],['accountPageTitle','accountPageTitle'],['accountPageSubtitle','accountPageSubtitle'],['loginTitle','loginTitle'],['loginText','loginText'],['customerLoginBtn','loginButton'],['accountLabel','accountLabel'],['logoutText','logoutText'],['accountNameLabel','nameLabel'],['accountPhoneLabel','phoneLabel'],['accountCityLabel','cityLabel'],['accountAddressLabel','addressLabel'],['accountSaveBtn','saveAccountText'],['navHomeText','navHomeText'],['navCategoriesText','navCategoriesText'],['navSearchText','navSearchText'],['navCartText','navCartText'],['navAccountText','navAccountText'],['languageTitle','languageTitle'],['languageNote','languageNote'],['langArPublic','languageArabicText'],['langFrPublic','languageFrenchText'],['langEnPublic','languageEnglishText'],['langPtPublic','languagePortugueseText'],['checkoutTitle','checkoutTitle'],['checkoutNameLabel','checkoutNameLabel'],['checkoutPhoneLabel','checkoutPhoneLabel'],['checkoutCityLabel','checkoutCityLabel'],['checkoutAddressLabel','checkoutAddressLabel'],['paymentLabel','paymentLabel'],['codLabel','codLabel'],['transferLabel','transferLabel'],['transferProofTitle','transferProofTitle'],['transferProofNote','transferProofNote'],['transferProofImageLabel','transferProofImageLabel'],['placeOrderBtn','confirmOrderText']];map.forEach(([id,key])=>siteText(id,ct(key)));const h=document.getElementById('siteHeroTitle');if(h)h.innerHTML=esc(ct('heroTitle')).replace(/\n/g,'<br>');const sb=document.getElementById('siteSearchButton');if(sb)sb.textContent=ct('searchPlaceholder');const si=document.getElementById('searchInput');if(si)si.placeholder=ct('searchPlaceholder');const hero=document.getElementById('siteHero'),trust=document.getElementById('siteTrust'),cats=document.getElementById('siteCategoriesSection'),prods=document.getElementById('siteProductsSection');if(hero)hero.style.display=c.heroVisible===false?'none':'';if(trust)trust.style.display=c.trustVisible===false?'none':'';if(cats)cats.style.display=c.categoriesVisible===false?'none':'';if(prods)prods.style.display=c.productsVisible===false?'none':'';if(hero)hero.style.background=c.heroImage?`linear-gradient(rgba(2,3,4,.45),rgba(7,16,30,.55)),url("${String(c.heroImage).replace(/"/g,'')}") center/cover no-repeat`:'';document.title=ct('seoTitle');const md=document.querySelector('meta[name="description"]');if(md)md.content=ct('seoDescription');const ot=document.querySelector('meta[property="og:title"]');if(ot)ot.content=ct('ogTitle');const od=document.querySelector('meta[property="og:description"]');if(od)od.content=ct('ogDescription');homeCategories.innerHTML=categoryButtons();allCategories.innerHTML=categoryButtons();applyGeneralSettings(generalSettings);renderStore();renderCart();renderMyOrders()}'''
index = replace_regex(index, r'function applySiteContent\(c=\{\}\)\{.*?\}\nfunction applyGeneralSettings', new_apply_site + '\nfunction applyGeneralSettings', 'apply site content')

index = replace_regex(index, r"function applyGeneralSettings\(d=\{\}\)\{.*?\}\nfunction applyLanguageSettings", "function applyGeneralSettings(d={}){generalSettings=d;const info=document.getElementById('bankTransferInfo');if(info){const parts=[];if(d.bankName)parts.push('البنك: '+d.bankName);if(d.bankHolder)parts.push('اسم الحساب: '+d.bankHolder);if(d.bankAccount)parts.push('رقم الحساب: '+d.bankAccount);info.textContent=parts.length?parts.join(' • '):ct('bankInfoEmptyMessage')}}\nfunction applyLanguageSettings", 'general settings')

