index = replace_regex(index, r'window\.saveAccount=async\(\)=>\{.*?\};\nfunction watchCustomerProfile', r'''window.saveAccount=async()=>{if(!currentUser)return customerLogin();const a={uid:currentUser.uid,email:currentUser.email||'',name:document.getElementById('accountName').value.trim(),phone:document.getElementById('accountPhone').value.trim(),city:document.getElementById('accountCity').value.trim(),address:document.getElementById('accountAddress').value.trim()};const st=document.getElementById('accountStatus');st.style.display='block';st.textContent=ct('accountSavingMessage');try{await setDoc(doc(db,'customerAccounts',currentUser.uid),{...a,updatedAt:serverTimestamp()},{merge:true});localStorage.setItem('MauriOne_account',JSON.stringify(a));st.className='notice success';st.textContent=ct('accountSavedMessage')}catch(e){console.error(e);st.className='notice';st.textContent=ct('accountSaveError')}};
function watchCustomerProfile''', 'save account')

