index = replace_regex(index, r"coProof\.addEventListener\('change',\(\)=>\{.*?\}\);", "coProof.addEventListener('change',()=>{const f=coProof.files?.[0];coProofPreview.innerHTML='';coProofPreview.classList.remove('show');if(!f)return;if(!f.type.startsWith('image/')){coProof.value='';return alert(ct('proofImageOnlyMessage'))}if(f.size>8*1024*1024){coProof.value='';return alert(ct('proofImageSizeMessage'))}const url=URL.createObjectURL(f);coProofPreview.innerHTML=`<img src=\"${url}\" alt=\"\">`;coProofPreview.classList.add('show')});", 'proof validation')
index = replace_regex(index, r'async function uploadPaymentProof\(file\)\{.*?\}\nwindow\.checkout', "async function uploadPaymentProof(file){const fd=new FormData();fd.append('file',file);fd.append('upload_preset',CLOUDINARY_PRESET);const res=await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD}/image/upload`,{method:'POST',body:fd});const data=await res.json();if(!res.ok||!data.secure_url)throw new Error(data?.error?.message||ct('proofUploadErrorMessage'));return data.secure_url}\nwindow.checkout", 'proof upload')
index = replace_regex(index, r'window\.checkout=\(\)=>\{.*?\};\nwindow\.placeOrder', r'''window.checkout=()=>{if(generalSettings.maintenance===true)return alert(ct('maintenanceMessage'));if(!cartRows().length)return alert(ct('cartEmptyAlert'));if(!currentUser){openStore('accountPage','navAccount');setTimeout(()=>alert(ct('loginRequiredMessage')),80);return}const a=account();coName.value=a.name||'';coPhone.value=a.phone||'';coCity.value=a.city||generalSettings.deliveryCity||'';coAddress.value=a.address||'';coPayment.value='cod';coProof.value='';coProofPreview.innerHTML='';coProofPreview.classList.remove('show');transferProofField.classList.remove('show');checkoutStatus.style.display='none';placeOrderBtn.style.display='block';placeOrderBtn.disabled=false;placeOrderBtn.textContent=ct('confirmOrderText');document.getElementById('checkoutOverlay').classList.add('open')};
window.placeOrder''', 'checkout')

new_place_order = r'''window.placeOrder=async()=>{const rows=cartRows();if(!rows.length)return;if(!currentUser){openStore('accountPage','navAccount');return}const customer={name:coName.value.trim(),phone:coPhone.value.trim(),city:coCity.value.trim(),address:coAddress.value.trim()};if(!customer.name||!customer.phone||!customer.address){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent=ct('requiredFieldsMessage');return}const isTransfer=coPayment.value==='transfer',proofFile=coProof.files?.[0]||null;if(isTransfer&&!proofFile){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent=ct('proofRequiredMessage');return}const items=rows.map(({p,qty})=>({productId:String(p.id),name:String(p.name||''),price:Number(p.price||0),qty:Number(qty||1),image:Array.isArray(p.images)&&p.images[0]?String(p.images[0]):''})),inventory={};if(items.length>6){checkoutStatus.style.display='block';checkoutStatus.className='notice';checkoutStatus.textContent=ct('maxProductsMessage');return}items.forEach(i=>inventory[i.productId]=i.qty);const total=items.reduce((sum,x)=>sum+x.price*x.qty,0),orderNo='MO-'+String(Date.now()).slice(-6);placeOrderBtn.disabled=true;placeOrderBtn.textContent=isTransfer?ct('orderUploadingProofMessage'):ct('orderCheckingStockMessage');try{const paymentProofUrl=isTransfer?await uploadPaymentProof(proofFile):'';placeOrderBtn.textContent=ct('orderReservingMessage');const orderRef=doc(collection(db,'orders')),trackingRef=doc(db,'orderTracking',orderRef.id),productRefs=items.map(i=>doc(db,'products',i.productId)),reservationRows=items.map(i=>{const id=orderRef.id+'_'+i.productId;return{id,ref:doc(db,'inventoryReservations',id),item:i}});await runTransaction(db,async tx=>{const snaps=[];for(const ref of productRefs)snaps.push(await tx.get(ref));const updates=[];for(let i=0;i<items.length;i++){const item=items[i],snap=snaps[i];if(!snap.exists())throw new Error('STOCK|'+item.name+'|0');const available=Number(snap.data().stock||0);if(!Number.isFinite(available)||available<item.qty)throw new Error('STOCK|'+item.name+'|'+Math.max(0,available||0));updates.push({ref:productRefs[i],stock:available-item.qty})}tx.set(orderRef,{orderNo,customerUid:currentUser.uid,customerEmail:currentUser.email||'',customer,items,total,payment:coPayment.value,paymentProofUrl,status:'new',inventoryManaged:true,inventory,createdAt:serverTimestamp()});tx.set(trackingRef,{orderNo,customerUid:currentUser.uid,status:'new',estimatedDelivery:'',updatedAt:serverTimestamp()});updates.forEach((u,i)=>{const r=reservationRows[i],item=items[i];tx.set(r.ref,{orderId:orderRef.id,productId:item.productId,customerUid:currentUser.uid,qty:item.qty,state:'reserved',createdAt:serverTimestamp()});tx.update(u.ref,{stock:u.stock,updatedAt:serverTimestamp(),lastInventoryReservationId:r.id})})});localStorage.setItem('MauriOne_account',JSON.stringify({...account(),...customer,uid:currentUser.uid,email:currentUser.email||''}));orderHistory.unshift({id:orderRef.id,orderNo,customerUid:currentUser.uid,items,total,payment:coPayment.value,status:'new',inventoryManaged:true,estimatedDelivery:'',updatedAt:new Date().toLocaleString('ar'),createdAt:Date.now()});saveOrders();connectTracking();cart=[];saveCart();updateBadge();renderCart();renderMyOrders();checkoutStatus.style.display='block';checkoutStatus.className='notice success';checkoutStatus.textContent=tpl(isTransfer?'orderSuccessTransferTemplate':'orderSuccessCodTemplate',{orderNo});placeOrderBtn.style.display='none'}catch(e){console.error(e);checkoutStatus.style.display='block';checkoutStatus.className='notice';const m=String(e?.message||'');if(m.startsWith('STOCK|')){const parts=m.split('|');checkoutStatus.textContent=tpl('stockUnavailableTemplate',{product:parts[1]||ct('genericProductText'),stock:Number(parts[2]||0)});renderCart()}else if(e?.code==='permission-denied'){checkoutStatus.textContent=ct('inventoryPermissionMessage')}else checkoutStatus.textContent=ct('orderErrorMessage')}finally{placeOrderBtn.disabled=false;placeOrderBtn.textContent=ct('confirmOrderText')}};'''
index = replace_regex(index, r'window\.placeOrder=async\(\)=>\{.*?\};\nonSnapshot\(doc\(db,\'storeSettings\'', new_place_order + "\nonSnapshot(doc(db,'storeSettings'", 'place order')

